// ── API functions ───────────────────────────────────────────────

/**
 * Upload an audio file.
 * Simulates upload progress via onProgress callback, then returns a job id.
 */
export async function uploadAudio(
  file: File,
  onProgress: ProgressCallback
): Promise<UploadResponse> {
  // Simulate upload progress in 10% increments
  for (let pct = 0; pct <= 100; pct += 10) {
    await sleep(200);
    onProgress(pct);
  }

  const id = `upload-${Date.now()}`;
  return { id, status: "queued" };
}

/**
 * Poll the job status.
 * In mock mode, walks through the state machine on successive calls.
 */
const pollCounters = new Map<string, number>();

export async function pollJobStatus(jobId: string): Promise<Upload> {
  await sleep(300); // simulate network

  const count = (pollCounters.get(jobId) ?? 0) + 1;
  pollCounters.set(jobId, count);

  // Walk through states based on how many times we've polled
  let status: Upload["status"];
  let transcript: string | null = null;
  let summary: string | null = null;

  if (count <= 2) {
    status = "queued";
  } else if (count <= 5) {
    status = "transcribing";
  } else if (count <= 7) {
    status = "summarizing";
    transcript = MOCK_TRANSCRIPT;
  } else {
    status = "done";
    transcript = MOCK_TRANSCRIPT;
    summary = MOCK_SUMMARY;
  }

  return {
    id: jobId,
    fileName: "uploaded-file.mp3",
    fileSize: 5_000_000,
    status,
    createdAt: new Date().toISOString(),
    transcript,
    summary,
    errorMessage: null,
  };
}

/** Fetch the list of past uploads. */
export async function fetchUploads(): Promise<Upload[]> {
  await sleep(500); // simulate network
  return MOCK_UPLOADS;
}

/** Fetch a single upload by id. */
export async function fetchUploadById(
  id: string
): Promise<Upload | null> {
  await sleep(400);
  return MOCK_UPLOADS.find((u) => u.id === id) ?? null;
}
